function floydWarshall(dist):
  n = dist.length
  for k in 0..n:
    for i in 0..n:
      for j in 0..n:
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

function bellmanFord(adj, n, source):
  dist = array(n, infinity)
  dist[source] = 0
  for i in 1..n - 1:
    for u in 0..n:
      for v in 0..n:
        if adj[u][v]:
          relax(u, v, dist)

function buildMST(edges, n):
  sort(edges by weight)
  parent = initParent(n)
  mst = []
  for edge in edges:
    if root(parent, edge.u) != root(parent, edge.v):
      link(parent, edge.u, edge.v)
      mst.push(edge)

function root(parent, x):
  if parent[x] != x:
    parent[x] = root(parent, parent[x])
  return parent[x]

