function hasCycle(head):
  slow = head
  fast = head
  while fast != null and fast.next != null:
    slow = slow.next
    fast = fast.next.next
    if slow == fast:
      return true
  return false

function sortColors(arr):
  low = 0
  mid = 0
  high = arr.length - 1
  while mid <= high:
    if arr[mid] == 0:
      swap(arr[low], arr[mid]); low++; mid++
    else if arr[mid] == 2:
      swap(arr[mid], arr[high]); high--
    else:
      mid++

function countSolutions(n, row, cols):
  if row == n:
    return 1
  count = 0
  for col in 0..n:
    if isSafe(row, col, cols):
      cols[row] = col
      count = count + countSolutions(n, row + 1, cols)
  return count

function findSubstring(text, pattern):
  for i in 0..text.length - pattern.length:
    match = true
    for j in 0..pattern.length:
      if text[i + j] != pattern[j]:
        match = false
        break
    if match:
      return i
  return -1

