function shortestPath(grid, start, goal):
  queue = [start]
  dist = map(start -> 0)
  while queue not empty:
    cell = queue.popFront()
    if cell == goal:
      return dist[cell]
    for neighbor in neighbors(cell):
      if neighbor not in dist:
        dist[neighbor] = dist[cell] + 1
        queue.push(neighbor)

function growMST(adj, n):
  key = array(n, infinity)
  key[0] = 0
  for count in 0..n:
    u = minKey(key, inMST)
    inMST[u] = true
    for v in 0..n:
      if adj[u][v] and not inMST[v]:
        key[v] = min(key[v], adj[u][v])

function kth(arr, k, low, high):
  if low == high:
    return arr[low]
  pivot = partition(arr, low, high)
  if k == pivot:
    return arr[k]
  if k < pivot:
    return kth(arr, k, low, pivot - 1)
  return kth(arr, k, pivot + 1, high)

function sieve(n):
  isPrime = array(n + 1, true)
  isPrime[0] = false
  isPrime[1] = false
  for p in 2..sqrt(n):
    if isPrime[p]:
      for multiple in p*p..n step p:
        isPrime[multiple] = false

function longestIncreasing(arr):
  dp = newBuffer(arr.length, 1)
  for i in 1..arr.length:
    for j in 0..i - 1:
      if arr[j] < arr[i]:
        dp[i] = max(dp[i], dp[j] + 1)
  return max(dp)

function commonSubseq(a, b):
  m = a.length
  n = b.length
  dp = matrix(m + 1, n + 1, 0)
  for i in 1..m:
    for j in 1..n:
      if a[i-1] == b[j-1]:
        dp[i][j] = dp[i-1][j-1] + 1
      else:
        dp[i][j] = max(dp[i-1][j], dp[i][j-1])
  return dp[m][n]

function editDistance(a, b):
  m = a.length
  n = b.length
  dp = matrix(m + 1, n + 1, 0)
  for i in 0..m:
    dp[i][0] = i
  for j in 0..n:
    dp[0][j] = j
  for i in 1..m:
    for j in 1..n:
      cost = a[i-1] == b[j-1] ? 0 : 1
      dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + cost)
  return dp[m][n]
